import os
import asyncio
import json
import uuid
from datetime import datetime
from typing import List, Dict, Any, Optional
from dataclasses import dataclass, asdict
from enum import Enum
import aiohttp
from fastapi import FastAPI, WebSocket, WebSocketDisconnect, HTTPException, UploadFile, File
from fastapi.responses import HTMLResponse, JSONResponse
from fastapi.staticfiles import StaticFiles
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel
import anthropic
from cerebras.cloud.sdk import Cerebras
from openai import OpenAI
from exa_py import Exa

# API kulcsok betöltése
CEREBRAS_API_KEY = os.environ.get("CEREBRAS_API_KEY")
XAI_API_KEY = os.environ.get("XAI_API_KEY")
EXA_API_KEY = os.environ.get("EXA_API_KEY")

# Kliensek inicializálása
cerebras_client = Cerebras(api_key=CEREBRAS_API_KEY)
grok_client = OpenAI(api_key=XAI_API_KEY, base_url="")
exa_client = Exa(api_key=EXA_API_KEY)

app = FastAPI()

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

class ResearchMode(str, Enum):
    QUICK = "quick"
    DEEP = "deep"

class TaskStatus(str, Enum):
    PENDING = "pending"
    RUNNING = "running"
    COMPLETED = "completed"
    FAILED = "failed"

@dataclass
class ResearchStep:
    step_id: str
    timestamp: str
    action: str
    query: Optional[str]
    model_used: str
    findings: str
    sources: List[Dict[str, str]]
    reasoning: str
    next_action: str

@dataclass
class ResearchTask:
    task_id: str
    query: str
    mode: ResearchMode
    status: TaskStatus
    created_at: str
    updated_at: str
    steps: List[ResearchStep]
    final_report: Optional[str]
    total_sources: int
    attachments: List[Dict[str, Any]]

class ConnectionManager:
    def __init__(self):
        self.active_connections: Dict[str, WebSocket] = {}

    async def connect(self, task_id: str, websocket: WebSocket):
        await websocket.accept()
        self.active_connections[task_id] = websocket

    def disconnect(self, task_id: str):
        if task_id in self.active_connections:
            del self.active_connections[task_id]

    async def send_update(self, task_id: str, data: Dict[str, Any]):
        if task_id in self.active_connections:
            try:
                await self.active_connections[task_id].send_json(data)
            except Exception as e:
                print(f"Error sending update: {e}")
                self.disconnect(task_id)

manager = ConnectionManager()
active_tasks: Dict[str, ResearchTask] = {}

class DeepResearchAgent:
    def __init__(self, task_id: str, query: str, mode: ResearchMode, attachments: List[Dict[str, Any]] = None):
        self.task_id = task_id
        self.query = query
        self.mode = mode
        self.attachments = attachments or []
        self.steps: List[ResearchStep] = []
        self.sources_found: List[Dict[str, str]] = []
        self.context_memory: List[str] = []
        self.max_iterations = 50 if mode == ResearchMode.DEEP else 15
        self.current_iteration = 0

    async def send_progress(self, step: ResearchStep):
        await manager.send_update(self.task_id, {
            "type": "step",
            "step": asdict(step)
        })

    async def cerebras_reasoning(self, prompt: str, context: List[str] = None) -> str:
        """Cerebras Qwen 235B Thinking model használata mély gondolkodáshoz"""
        messages = [
            {"role": "system", "content": "Te egy elitnyomozó vagy, aki képes mély következtetésekre, összefüggések felfedezésére. Gondolkodj lépésről lépésre, következtess, és mindig keress rejtett kapcsolatokat."}
        ]

        if context:
            messages.append({"role": "user", "content": f"Kontextus:\n" + "\n".join(context[-10:])})

        messages.append({"role": "user", "content": prompt})

        response = cerebras_client.chat.completions.create(
            model="qwen-3-235b-a22b-thinking-2507",
            messages=messages,
            temperature=0.7,
            max_tokens=8000
        )

        return response.choices[0].message.content

    async def cerebras_fast(self, prompt: str) -> str:
        """Cerebras GPT-OSS 120B gyors válaszokhoz"""
        response = cerebras_client.chat.completions.create(
            model="gpt-oss-120b",
            messages=[{"role": "user", "content": prompt}],
            temperature=0.5,
            max_tokens=65000
        )
        return response.choices[0].message.content

    async def grok_analyze(self, prompt: str, use_search: bool = False) -> str:
        """Grok 4 Fast reasoning mély elemzéshez"""
        response = grok_client.chat.completions.create(
            model="grok-4-fast-reasoning",
            messages=[{"role": "user", "content": prompt}],
            temperature=0.6,
            max_tokens=50000,
            live_search=use_search
        )
        return response.choices[0].message.content

    async def exa_search(self, query: str, num_results: int = 100) -> List[Dict[str, Any]]:
        """Exa AI keresés maximális találatokkal"""
        try:
            response = exa_client.search_and_contents(
                query=query,
                type="auto",
                num_results=num_results,
                text={"max_characters": 8000},
                highlights=True,
                use_autoprompt=True,
                livecrawl="always"
            )

            results = []
            for result in response.results:
                results.append({
                    "url": result.url,
                    "title": result.title,
                    "text": result.text[:5000] if result.text else "",
                    "highlights": result.highlights[:10] if hasattr(result, 'highlights') else [],
                    "published_date": result.published_date if hasattr(result, 'published_date') else None
                })

            return results
        except Exception as e:
            print(f"Exa search error: {e}")
            return []

    async def plan_research(self) -> List[str]:
        """Kutatási terv létrehozása"""
        planning_prompt = f"""
Te egy világszínvonalú kutatási stratéga vagy. Feladatod egy átfogó, többlépéses kutatási terv készítése.

Kutatási kérdés: {self.query}

Csatolt anyagok: {len(self.attachments)} fájl

Készíts 8-12 specifikus kutatási kérdést, amelyek:
1. Feltárják a fő témát
2. Kapcsolódó kontextust és hátteret keresnek
3. Ellentmondásokat és alternatív nézeteket vizsgálnak
4. Mélyebb összefüggéseket keresnek
5. Kereszthivatkozásokat és validációt végeznek

Minden kérdés legyen konkrét és kereshető.
Formátum: Egy kérdés soronként, számozás nélkül.
"""

        plan = await self.cerebras_reasoning(planning_prompt)
        questions = [q.strip() for q in plan.split('\n') if q.strip() and '?' in q]
        return questions[:12]

    async def investigate_query(self, query: str, iteration: int) -> ResearchStep:
        """Egyetlen kutatási lépés végrehajtása"""
        step_id = str(uuid.uuid4())

        # Exa keresés
        search_results = await self.exa_search(query, num_results=100 if self.mode == ResearchMode.DEEP else 30)
        self.sources_found.extend(search_results)

        # Eredmények összegzése
        sources_text = "\n\n".join([
            f"Forrás [{i+1}]: {r['title']}\nURL: {r['url']}\n{r['text'][:1000]}"
            for i, r in enumerate(search_results[:15])
        ])

        # Grok elemzés
        analysis_prompt = f"""
Elemezd ezeket a forrásokat és találj rejtett összefüggéseket:

Eredeti kutatási kérdés: {self.query}
Jelenlegi specifikus kérdés: {query}

Források:
{sources_text}

Feladatod:
1. Elemezd a forrásokat mélységükben
2. Találd meg a kapcsolatokat és mintákat
3. Azonosíts ellentmondásokat
4. Határozz meg következtetéseket
5. Javasolj konkrét további kutatási irányokat

Adj strukturált választ.
"""

        analysis = await self.grok_analyze(analysis_prompt, use_search=True)
        self.context_memory.append(f"Q: {query}\nA: {analysis}")

        # Következő lépés meghatározása
        next_action_prompt = f"""
Eddigi kutatás: {len(self.steps)} lépés
Jelenlegi megállapítások: {analysis[:500]}

Mit kellene legközelebb megvizsgálni? Add meg a következő konkrét kutatási kérdést vagy irányt.
Csak a kérdést add meg, magyarázat nélkül.
"""

        next_action = await self.cerebras_fast(next_action_prompt)

        step = ResearchStep(
            step_id=step_id,
            timestamp=datetime.now().isoformat(),
            action="investigate",
            query=query,
            model_used="Grok-4-Fast + Exa AI",
            findings=analysis,
            sources=[{"title": r['title'], "url": r['url']} for r in search_results[:10]],
            reasoning=f"Iteráció {iteration}: Vizsgálat és elemzés",
            next_action=next_action.strip()
        )

        self.steps.append(step)
        await self.send_progress(step)

        return step

    async def synthesize_report(self) -> str:
        """Végső jelentés szintézise"""
        synthesis_prompt = f"""
Te egy vezető kutató elemző vagy. Készíts átfogó, részletes kutatási jelentést.

Eredeti kérdés: {self.query}

Kutatási lépések száma: {len(self.steps)}
Megvizsgált források: {len(self.sources_found)}

Kutatási folyamat összefoglalója:
{chr(10).join([f"{i+1}. {s.query}: {s.findings[:300]}..." for i, s in enumerate(self.steps)])}

Készíts professzionális, strukturált jelentést:

# EXECUTIVE SUMMARY
# KUTATÁSI MÓDSZERTAN
# KULCSFONTOSSÁGÚ MEGÁLLAPÍTÁSOK
# RÉSZLETES ELEMZÉS (több szakasz)
# KÖVETKEZTETÉSEK
# AJÁNLÁSOK
# FORRÁSOK

A jelentés legyen minimum 3000 szó, markdown formátumban.
Hivatkozz konkrét forrásokra [1], [2] stb.
"""

        report = await self.grok_analyze(synthesis_prompt, use_search=False)

        # Források hozzáadása
        sources_section = "\n\n## FORRÁSOK\n\n"
        unique_sources = {s['url']: s for s in self.sources_found}.values()
        for i, source in enumerate(list(unique_sources)[:100], 1):
            sources_section += f"[{i}] {source['title']}\n{source['url']}\n\n"

        return report + sources_section

    async def run(self) -> ResearchTask:
        """Fő kutatási folyamat futtatása"""
        task = active_tasks[self.task_id]
        task.status = TaskStatus.RUNNING
        task.updated_at = datetime.now().isoformat()

        try:
            # 1. Kutatási terv
            research_questions = await self.plan_research()

            await manager.send_update(self.task_id, {
                "type": "plan",
                "questions": research_questions
            })

            # 2. Iteratív kutatás
            for i, question in enumerate(research_questions):
                if self.current_iteration >= self.max_iterations:
                    break

                await self.investigate_query(question, i + 1)
                self.current_iteration += 1

                # Rövid várakozás a rate limit kezelésére
                await asyncio.sleep(1)

            # 3. Adaptív mélyebb kutatás
            if self.mode == ResearchMode.DEEP:
                for _ in range(10):
                    if self.current_iteration >= self.max_iterations:
                        break

                    last_step = self.steps[-1]
                    if last_step.next_action and len(last_step.next_action) > 10:
                        await self.investigate_query(last_step.next_action, self.current_iteration + 1)
                        self.current_iteration += 1
                        await asyncio.sleep(1)

            # 4. Végső jelentés
            final_report = await self.synthesize_report()

            task.final_report = final_report
            task.status = TaskStatus.COMPLETED
            task.updated_at = datetime.now().isoformat()
            task.steps = self.steps
            task.total_sources = len(self.sources_found)

            await manager.send_update(self.task_id, {
                "type": "completed",
                "report": final_report,
                "total_sources": len(self.sources_found)
            })

            return task

        except Exception as e:
            task.status = TaskStatus.FAILED
            task.updated_at = datetime.now().isoformat()
            await manager.send_update(self.task_id, {
                "type": "error",
                "error": str(e)
            })
            raise

# API Endpoints
@app.post("/api/research/start")
async def start_research(query: str, mode: str = "quick", files: List[UploadFile] = File(None)):
    task_id = str(uuid.uuid4())

    attachments = []
    if files:
        for file in files:
            content = await file.read()
            attachments.append({
                "filename": file.filename,
                "content_type": file.content_type,
                "size": len(content),
                "content": content.decode('utf-8', errors='ignore')[:50000]
            })

    task = ResearchTask(
        task_id=task_id,
        query=query,
        mode=ResearchMode(mode),
        status=TaskStatus.PENDING,
        created_at=datetime.now().isoformat(),
        updated_at=datetime.now().isoformat(),
        steps=[],
        final_report=None,
        total_sources=0,
        attachments=attachments
    )

    active_tasks[task_id] = task

    # Háttérben futtatás
    asyncio.create_task(run_research_task(task_id, query, mode, attachments))

    return {"task_id": task_id, "status": "started"}

async def run_research_task(task_id: str, query: str, mode: str, attachments: List[Dict[str, Any]]):
    agent = DeepResearchAgent(task_id, query, ResearchMode(mode), attachments)
    await agent.run()

@app.websocket("/ws/{task_id}")
async def websocket_endpoint(websocket: WebSocket, task_id: str):
    await manager.connect(task_id, websocket)
    try:
        while True:
            await websocket.receive_text()
    except WebSocketDisconnect:
        manager.disconnect(task_id)

@app.get("/api/research/{task_id}")
async def get_research_status(task_id: str):
    if task_id not in active_tasks:
        raise HTTPException(status_code=404, detail="Task not found")

    task = active_tasks[task_id]
    return JSONResponse(content=asdict(task))

@app.get("/api/research/{task_id}/report")
async def get_report(task_id: str):
    if task_id not in active_tasks:
        raise HTTPException(status_code=404, detail="Task not found")

    task = active_tasks[task_id]
    if not task.final_report:
        raise HTTPException(status_code=404, detail="Report not ready")

    return {"report": task.final_report}

@app.get("/")
async def get_index():
    with open("index.html", "r", encoding="utf-8") as f:
        return HTMLResponse(content=f.read())

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)
