<body>
    <div class="app-container">
        <header class="header">
            <div class="header-content">
                <div class="logo">🔍 Autonóm Kutatási Ágens</div>
                <div class="mode-switch">
                    <button class="mode-btn active" data-mode="quick">Gyors mód</button>
                    <button class="mode-btn" data-mode="deep">Mélyreható kutatás</button>
                </div>
            </div>
        </header>

        <main class="main-content">
            <div class="search-container">
                <textarea 
                    class="search-input" 
                    id="searchInput"
                    placeholder="Mire vagy kíváncsi? Adj meg bármilyen kutatási kérdést, feltölthetsz dokumentumokat, képeket..."
                    rows="3"
                ></textarea>
                <div class="search-actions">
                    <div class="file-upload">
                        <label for="fileInput" class="file-btn">
                            📎 Fájl feltöltése
                        </label>
                        <input type="file" id="fileInput" class="file-input" multiple accept=".pdf,.txt,.doc,.docx,.png,.jpg,.jpeg">
                        <span id="fileCount" class="file-count" style="color: var(--text-tertiary); font-size: 14px;"></span>
                    </div>
                    <button class="search-btn" id="searchBtn">Kutatás indítása</button>
                </div>
            </div>

            <div id="researchPanel" class="research-panel hidden">
                <div class="status-indicator">
                    <div class="status-dot running" id="statusDot"></div>
                    <span id="statusText">Kutatás inicializálása...</span>
                </div>

                <div class="stats-grid" id="statsGrid">
                    <div class="stat-card">
                        <div class="stat-value" id="stepCount">0</div>
                        <div class="stat-label">Kutatási lépés</div>
                    </div>
                    <div class="stat-card">
                        <div class="stat-value" id="sourceCount">0</div>
                        <div class="stat-label">Forrás feldolgozva</div>
                    </div>
                    <div class="stat-card">
                        <div class="stat-value" id="elapsedTime">0:00</div>
                        <div class="stat-label">Eltelt idő</div>
                    </div>
                </div>

                <div class="progress-bar">
                    <div class="progress-fill" id="progressFill" style="width: 0%"></div>
                </div>

                <div class="research-steps" id="researchSteps"></div>

                <div id="reportContainer" class="report-container hidden"></div>
            </div>
        </main>
    </div>

    <script>
        let currentMode = 'quick';
        let currentTaskId = null;
        let ws = null;
        let startTime = null;
        let timerInterval = null;
        let selectedFiles = [];

        // Mode switching
        document.querySelectorAll('.mode-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                document.querySelectorAll('.mode-btn').forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
                currentMode = btn.dataset.mode;
            });
        });

        // File upload
        document.getElementById('fileInput').addEventListener('change', (e) => {
            selectedFiles = Array.from(e.target.files);
            const fileCount = document.getElementById('fileCount');
            if (selectedFiles.length > 0) {
                fileCount.textContent = `${selectedFiles.length} fájl kiválasztva`;
            } else {
                fileCount.textContent = '';
            }
        });

        // Start research
        document.getElementById('searchBtn').addEventListener('click', async () => {
            const query = document.getElementById('searchInput').value.trim();
            if (!query) {
                alert('Kérlek add meg a kutatási kérdést!');
                return;
            }

            const formData = new FormData();
            formData.append('query', query);
            formData.append('mode', currentMode);

            selectedFiles.forEach(file => {
                formData.append('files', file);
            });

            try {
                document.getElementById('searchBtn').disabled = true;
                const response = await fetch('/api/research/start', {
                    method: 'POST',
                    body: formData
                });

                const data = await response.json();
                currentTaskId = data.task_id;

                document.getElementById('researchPanel').classList.remove('hidden');
                document.getElementById('researchSteps').innerHTML = '';
                document.getElementById('reportContainer').classList.add('hidden');

                connectWebSocket(currentTaskId);
                startTimer();

            } catch (error) {
                console.error('Error starting research:', error);
                alert('Hiba történt a kutatás indításakor');
                document.getElementById('searchBtn').disabled = false;
            }
        });

        function connectWebSocket(taskId) {
            const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
            ws = new WebSocket(`${protocol}//${window.location.host}/ws/${taskId}`);

            ws.onmessage = (event) => {
                const data = JSON.parse(event.data);
                handleWebSocketMessage(data);
            };

            ws.onerror = (error) => {
                console.error('WebSocket error:', error);
            };

            ws.onclose = () => {
                console.log('WebSocket closed');
            };
        }

        function handleWebSocketMessage(data) {
            switch(data.type) {
                case 'plan':
                    document.getElementById('statusText').textContent = `Kutatási terv elkészítve: ${data.questions.length} kérdés`;
                    break;

                case 'step':
                    addResearchStep(data.step);
                    updateStats();
                    break;

                case 'completed':
                    completeResearch(data);
                    break;

                case 'error':
                    handleError(data.error);
                    break;
            }
        }

        function addResearchStep(step) {
            const stepsContainer = document.getElementById('researchSteps');
            const stepCard = document.createElement('div');
            stepCard.className = 'step-card';

            const sourcesHtml = step.sources.map(source => 
                `${source.title}`
            ).join('');

            stepCard.innerHTML = `
                <div class="step-header">
                    <div class="step-title">Lépés ${stepsContainer.children.length + 1}</div>
                    <div class="step-model">${step.model_used}</div>
                </div>
                <div class="step-query">${step.query}</div>
                <div class="step-findings">${step.findings.substring(0, 500)}...</div>
                <div class="step-sources">${sourcesHtml}</div>
            `;

            stepsContainer.appendChild(stepCard);
            stepCard.scrollIntoView({ behavior: 'smooth', block: 'end' });
        }

        function updateStats() {
            const stepCount = document.getElementById('researchSteps').children.length;
            document.getElementById('stepCount').textContent = stepCount;

            const maxSteps = currentMode === 'deep' ? 50 : 15;
            const progress = Math.min((stepCount / maxSteps) * 100, 100);
            document.getElementById('progressFill').style.width = `${progress}%`;
        }

        function completeResearch(data) {
            document.getElementById('statusDot').classList.remove('running');
            document.getElementById('statusDot').classList.add('completed');
            document.getElementById('statusText').textContent = 'Kutatás befejezve!';
            document.getElementById('sourceCount').textContent = data.total_sources;
            document.getElementById('searchBtn').disabled = false;

            if (timerInterval) {
                clearInterval(timerInterval);
            }

            const reportContainer = document.getElementById('reportContainer');
            reportContainer.innerHTML = marked.parse(data.report);
            reportContainer.classList.remove('hidden');
            reportContainer.scrollIntoView({ behavior: 'smooth' });
        }

        function handleError(error) {
            alert(`Hiba történt: ${error}`);
            document.getElementById('searchBtn').disabled = false;
            if (timerInterval) {
                clearInterval(timerInterval);
            }
        }

        function startTimer() {
            startTime = Date.now();
            timerInterval = setInterval(() => {
                const elapsed = Math.floor((Date.now() - startTime) / 1000);
                const minutes = Math.floor(elapsed / 60);
                const seconds = elapsed % 60;
                document.getElementById('elapsedTime').textContent = 
                    `${minutes}:${seconds.toString().padStart(2, '0')}`;
            }, 1000);
        }

        // Markdown parser (simplified)
        const marked = {
            parse: (text) => {
                return text
                    .replace(/^### (.*$)/gim, '<h3>$1</h3>')
                    .replace(/^## (.*$)/gim, '<h2>$1</h2>')
                    .replace(/^# (.*$)/gim, '<h1>$1</h1>')
                    .replace(/\*\*(.*)\*\*/gim, '<strong>$1</strong>')
                    .replace(/\*(.*)\*/gim, '<em>$1</em>')
                    .replace(/\[(.*?)\]/gim, '<sup>$1</sup>')
                    .replace(/\n/gim, '<br>');
            }
        };
    </script>
</body>
