```python
from fastapi import FastAPI, UploadFile, File, WebSocket
from fastapi.responses import HTMLResponse
from fastapi.middleware.cors import CORSMiddleware
import uuid
import os

app = FastAPI()
app.add_middleware(
    CORSMiddleware, allow_origins=["*"], allow_methods=["*"], allow_headers=["*"]
)

tasks = {}

@app.post("/api/research/start")
async def start(query: str, mode: str, files: list[UploadFile] = File(None)):
    task_id = str(uuid.uuid4())
    tasks[task_id] = {"status": "started", "query": query, "mode": mode}
    # Itt illeszd be a modellspecifikus kutatási folyamatokat!
    return {"task_id": task_id}

@app.get("/api/research/{task_id}")
async def status(task_id: str):
    return tasks.get(task_id, {"error": "not found"})

@app.get("/", response_class=HTMLResponse)
async def get_root():
    with open("index.html", encoding="utf-8") as f:
        return f.read()

@app.websocket("/ws/{task_id}")
async def websocket_endpoint(websocket: WebSocket, task_id: str):
    await websocket.accept()
    try:
        while True:
            await websocket.receive_text()
            await websocket.send_json(tasks.get(task_id, {}))
    except Exception:
        pass
